import{_ as a,o,c,a2 as t}from"./chunks/framework.DgVVaeR-.js";const p=JSON.parse('{"title":"セキュリティ & 電卓パーサー仕様","description":"CalculatorEngine の構文解析パーサー、パターンC解錠、FLAG_SECURE","frontmatter":{"title":"セキュリティ & 電卓パーサー仕様","description":"CalculatorEngine の構文解析パーサー、パターンC解錠、FLAG_SECURE"},"headers":[],"relativePath":"dev/security-engine.md","filePath":"dev/security-engine.md","lastUpdated":1791086115000}'),r={name:"dev/security-engine.md"};function l(n,e,d,i,s,u){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="セキュリティ-電卓パーサー仕様" tabindex="-1">セキュリティ &amp; 電卓パーサー仕様 <a class="header-anchor" href="#セキュリティ-電卓パーサー仕様" aria-label="Permalink to &quot;セキュリティ &amp; 電卓パーサー仕様&quot;">​</a></h1><hr><h2 id="演算評価エンジン-calculatorengine" tabindex="-1">演算評価エンジン (<code>CalculatorEngine</code>) <a class="header-anchor" href="#演算評価エンジン-calculatorengine" aria-label="Permalink to &quot;演算評価エンジン (`CalculatorEngine`)&quot;">​</a></h2><ul><li><strong>字句解析 (<code>tokenize</code>)</strong>: 入力文字列から数値および演算子 (<code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>) を抽出。</li><li><strong>再帰降下パーサー (Recursive Descent Parser)</strong>: <ul><li><code>parseAddSub</code>: 加算・減算の評価</li><li><code>parseMulDiv</code>: 乗算・除算の評価（内部ではゼロ除算を <code>NaN</code> とし、公開関数 <code>evaluate</code> は <code>null</code> に変換）</li><li><code>parseUnary</code>: 単項符号の評価</li><li><code>parsePrimary</code>: 数値リテラルの評価</li></ul></li></ul><hr><h2 id="ステルス解錠メカニズム" tabindex="-1">ステルス解錠メカニズム <a class="header-anchor" href="#ステルス解錠メカニズム" aria-label="Permalink to &quot;ステルス解錠メカニズム&quot;">​</a></h2><ul><li><strong>通常解錠</strong>: 設定 PIN コードを入力し、<code>=</code> ボタンタップで解除。</li><li><strong>パターンC (右上隅タップ解錠)</strong>: 右上領域の連続タップで緊急解錠ダイアログ (<code>OverlayDialog</code>) 起動。</li><li><strong>動的コンポーネント切り替え</strong>: <code>PackageManager.setComponentEnabledSetting</code> により、アプリ表示名 (<code>dummyAppName</code>) およびアイコン (<code>dummyIconVariant</code>) を動的変更。</li></ul><h2 id="pinと評価失敗" tabindex="-1">PINと評価失敗 <a class="header-anchor" href="#pinと評価失敗" aria-label="Permalink to &quot;PINと評価失敗&quot;">​</a></h2><p>PIN設定画面は6桁入力を扱います。<code>CalculatorEngine.evaluate</code> は空入力、未知の文字、構文エラー、無限大などでも <code>null</code> を返します。電卓画面はアプリロックへの入口を変えるもので、DBや画像ファイル全体を暗号化する機能ではありません。</p>',9)])])}const h=a(r,[["render",l]]);export{p as __pageData,h as default};
